/**
 * A fully resolved prompt ready to be sent to an LLM.
 *
 * @param Output the type of the parsed LLM response.
 * @param ToolExecutor an object whose methods implement the template's tools,
 *   or [NoTools] if the template has no tools.
 *
 * Build and send the API request using [systemMessage], [userMessage],
 * [examples], and [tools]. If the model requests tool calls, dispatch
 * them with [executeTools] and then parse the final response with [parseResponse].
 */
data class Prompt<out Output, in ToolExecutor>(
    /** Metadata for this prompt. */
    val meta: Meta,
    val systemMessage: String,
    val userMessage: String,
    /** Few-shot examples. */
    val examples: List<FewShotExample>,
    /** The tools which can be called by the LLM, keyed by tool name. */
    val tools: Map<String, Tool>,
    val outputFormat: OutputFormat,
    val templateId: TemplateId,
    private val fromJson: (String) -> Output,
) {
    /**
     * Parse an LLM response into the expected output type.
     */
    fun parseResponse(response: String): Output {
        return doParseResponse(response, outputFormat, templateId, fromJson)
    }

    /**
     * Execute the given tool calls in parallel.
     */
    suspend fun executeTools(
        toolCalls: Iterable<ToolCall>,
        toolExecutor: ToolExecutor,
    ): List<ToolCallResponse> {
        val namespace = templateId.toString().split(':')[0]
        return coroutineScope {
            toolCalls.map { call ->
                async {
                    executeToolCall(call, namespace, toolExecutor as Any)
                }
            }.awaitAll()
        }
    }
}

/**
 * The expected format of the model output.
 */
sealed class OutputFormat

data class JsonOutputFormat internal constructor(
    val stringifiedJsonSchema: String,
    /** Strict JSON schema of the expected output, ready to pass to your LLM SDK. */
    val jsonSchema: JsonObject,
    /**
     * Whether the output type is or contains a recursive type, in which case
     * [jsonSchema] contains recursive references (`$ref`).
     *
     * Some LLM providers (namely Anthropic) do not accept recursive types in the
     * JSON schema of a structured output. If this is `true` and your provider
     * rejects the schema, a workaround is to ask the SDK for a tool call instead:
     * define a single tool whose input schema is [jsonSchema], force the model to
     * call it, and parse the tool call's input as the output.
     */
    val hasRecursiveType: Boolean,
) : OutputFormat()

class TextOutputFormat : OutputFormat()

data class Tool(
    val name: String,
    val description: String,
    val inputJsonSchema: JsonObject,
)

/**
 * A single few-shot example consisting of a user message, optional intermediate
 * tool-call steps, and the expected response.
 */
data class FewShotExample(
    val userMessage: String,
    val steps: List<StepExample>,
    val response: String,
)

/**
 * One step within a few-shot example, containing the tool
 * calls made at that step.
 */
data class StepExample(
    val toolCalls: List<ToolCallExample>,
)

/** A single tool call recorded inside an intermediate step. */
data class ToolCallExample(
    val callId: String,
    val toolName: String,
    val stringifiedInput: String,
    val stringifiedOutput: String,
)

data class ToolCall(
    val callId: String,
    val toolName: String,
    val stringifiedInput: String,
)

data class ToolCallResponse(
    val callId: String,
    /**
     * The JSON-stringified output of the tool call:
     * - On success, contains the JSON-serialized return value of the tool.
     * - On failure, contains a JSON object with a single "error" key containing
     *   the error message (e.g. `{"error": "..."}`).
     *
     * Integration guide:
     * - **OpenAI / Gemini SDKs**: Forward `stringifiedOutput` directly as the
     *   tool result content and ignore the `error` field.
     * - **Anthropic SDK**: Check if `error` is set. If set, mark `is_error = true`
     *   in the tool result block and pass the error message to `content`. Otherwise,
     *   pass `stringifiedOutput` to `content`.
     */
    val stringifiedOutput: String,
    /**
     * The error message if the tool call failed, or `null` on success.
     *
     * Set when tool argument parsing fails, when the tool itself returns an error,
     * or when the requested tool is not found.
     */
    val error: String? = null,
)

object NoTools
